1	import 'package:cerne/features/vault/data/local_auth_biometric_data_source.dart';
2	import 'package:cerne/features/vault/data/vault_secure_storage.dart';
3	import 'package:cerne/features/vault/domain/entities/biometric_capability.dart';
4	import 'package:cerne/features/vault/domain/repositories/vault_repository.dart';
5	import 'package:flutter/services.dart';
6	
7	/// Maps [LocalAuthBiometricDataSource]/`local_auth` results into
8	/// [BiometricCapability]/[BiometricAuthOutcome] before returning (RNF06).
9	/// `lastUnlockedAt`/`backgroundedAt` are held in-memory only, never
10	/// persisted (data-model.md Vault Lock State) — this class is registered as
11	/// a `get_it` `lazySingleton`, one instance for the app's process lifetime.
12	class VaultRepositoryImpl implements VaultRepository {
13	  VaultRepositoryImpl({
14	    required this._secureStorage,
15	    required this._biometricDataSource,
16	  });
17	
18	  final VaultSecureStorage _secureStorage;
19	  final LocalAuthBiometricDataSource _biometricDataSource;
20	
21	  DateTime? _backgroundedAt;
22	  DateTime? _lastUnlockedAt;
23	
24	  @override
25	  Future<bool> hasPinConfigured() => _secureStorage.hasPinConfigured();
26	
27	  @override
28	  Future<void> savePin(String pin) => _secureStorage.savePin(pin);
29	
30	  @override
31	  Future<bool> verifyPin(String pin) => _secureStorage.verifyPin(pin);
32	
33	  @override
34	  Future<BiometricCapability> checkBiometricCapability() async {
35	    final isSupported = await _biometricDataSource.isDeviceSupported();
36	    final canCheck = await _biometricDataSource.canCheckBiometrics();
37	    if (!isSupported || !canCheck) return BiometricCapability.noHardware;
38	
39	    final enrolled = await _biometricDataSource.getAvailableBiometrics();
40	    if (enrolled.isNotEmpty) return BiometricCapability.available;
41	
42	    // Hardware is present but nothing is currently enrolled. The local
43	    // biometrics-preference mirror tells us whether this device previously
44	    // had biometrics working for this unit (osDisabled) or never did
45	    // (notEnrolled) — the Edge Cases' "OS-level disable between sessions".
46	    final wasPreferred = await _secureStorage.readBiometricPreference();
47	    return wasPreferred
48	        ? BiometricCapability.osDisabled
49	        : BiometricCapability.notEnrolled;
50	  }
51	
52	  @override
53	  Future<BiometricAuthOutcome> attemptBiometricAuth() async {
54	    try {
55	      final success = await _biometricDataSource.authenticate();
56	      return success
57	          ? BiometricAuthOutcome.success
58	          : BiometricAuthOutcome.failed;
59	    } on PlatformException {
60	      // Capability changed between DetermineVaultEntryUseCase's check and
61	      // this call, or some other platform-level error (contracts/vault-repository.md).
62	      return BiometricAuthOutcome.notAvailable;
63	    }
64	  }
65	
66	  @override
67	  Future<bool> isBiometricPreferenceEnabled() =>
68	      _secureStorage.readBiometricPreference();
69	
70	  @override
71	  Future<void> setBiometricPreferenceLocally(bool enabled) =>
72	      _secureStorage.writeBiometricPreference(enabled);
73	
74	  @override
75	  void recordBackgrounded(DateTime at) => _backgroundedAt = at;
76	
77	  @override
78	  DateTime? consumeBackgroundedAt() {
79	    final value = _backgroundedAt;
80	    _backgroundedAt = null;
81	    return value;
82	  }
83	
84	  @override
85	  void markUnlocked(DateTime at) => _lastUnlockedAt = at;
86	
87	  @override
88	  DateTime? get lastUnlockedAt => _lastUnlockedAt;
89	}
90

